from __future__ import annotations

from .models import Findings
from .tokenizer import KeyValue, SectionHeader

MAX_PORT = 65535
VALID_MODES = frozenset({"dev", "prod", "test"})


# ------------------------------------------------------------ section rules

def check_section_name(header: SectionHeader, findings: Findings) -> None:
    if header.name == "":
        findings.add_error(header.line_no, "empty section name")


def check_duplicate_section(
    header: SectionHeader, seen: list[str], findings: Findings
) -> bool:
    """Returns True if this header names a NEW (previously unseen) section."""
    if header.name != "" and header.name in seen:
        findings.add_error(header.line_no, f"duplicate section {header.name}")
        return False
    if header.name != "":
        seen.append(header.name)
    return True


def check_header_closed(header: SectionHeader, findings: Findings) -> None:
    if not header.closed:
        findings.add_error(header.line_no, "unclosed section header")


# --------------------------------------------------------------- pair rules

def check_key_outside_section(line_no: int, findings: Findings) -> bool:
    findings.add_error(line_no, "key outside section")
    return False


def check_empty_key(pair: KeyValue, findings: Findings) -> bool:
    if pair.key == "":
        findings.add_error(pair.line_no, "empty key")
        return False
    return True


def check_duplicate_key(
    pair: KeyValue, keys_in_section: list[str], findings: Findings
) -> None:
    if pair.key in keys_in_section:
        findings.add_error(pair.line_no, f"duplicate key {pair.key}")
    else:
        keys_in_section.append(pair.key)


def check_empty_value(pair: KeyValue, findings: Findings) -> None:
    if pair.value == "":
        findings.add_warning(pair.line_no, f"empty value for {pair.key}")


def check_port(pair: KeyValue, findings: Findings) -> None:
    if not pair.value.isdigit():
        findings.add_error(pair.line_no, "port must be a number")
    elif int(pair.value) > MAX_PORT:
        findings.add_error(pair.line_no, "port out of range")


def check_mode(pair: KeyValue, findings: Findings) -> None:
    if pair.value not in VALID_MODES:
        findings.add_error(pair.line_no, f"bad mode {pair.value}")
